/* ============================================
   ClipCast Design System
   ============================================ */

/* --- CSS Variables (OKLCH Color System) --- */
:root {
  /* Brand Colors */
  --brand-primary: oklch(55% 0.18 255);
  --brand-primary-hover: oklch(48% 0.2 255);
  --brand-accent: oklch(68% 0.2 45);
  --brand-accent-hover: oklch(62% 0.22 45);

  /* Text */
  --text-primary: oklch(22% 0.02 265);
  --text-secondary: oklch(45% 0.03 265);
  --text-muted: oklch(58% 0.02 265);
  --text-on-primary: oklch(99% 0.005 265);

  /* Backgrounds */
  --bg-white: oklch(100% 0 0);
  --bg-surface: oklch(98% 0.005 265);
  --bg-subtle: oklch(95% 0.01 265);
  --bg-elevated: oklch(100% 0 0);
  --bg-dark: oklch(25% 0.03 265);

  /* Gradients */
  --gradient-hero: linear-gradient(135deg, oklch(96% 0.04 265) 0%, oklch(98% 0.02 280) 50%, oklch(97% 0.03 300) 100%);
  --gradient-primary: linear-gradient(135deg, var(--brand-primary) 0%, oklch(50% 0.22 270) 100%);
  --gradient-accent: linear-gradient(135deg, var(--brand-accent) 0%, oklch(60% 0.24 40) 100%);

  /* Spacing Scale */
  --space-1: 0.25rem;
  --space-2: 0.5rem;
  --space-3: 0.75rem;
  --space-4: 1rem;
  --space-5: 1.25rem;
  --space-6: 1.5rem;
  --space-8: 2rem;
  --space-10: 2.5rem;
  --space-12: 3rem;
  --space-16: 4rem;
  --space-20: 5rem;
  --space-24: 6rem;
  --space-32: 8rem;

  /* Typography */
  --font-sans: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  --font-mono: 'SF Mono', Monaco, monospace;

  --text-xs: 0.75rem;
  --text-sm: 0.875rem;
  --text-base: 1rem;
  --text-lg: 1.125rem;
  --text-xl: 1.25rem;
  --text-2xl: 1.5rem;
  --text-3xl: 1.875rem;
  --text-4xl: 2.25rem;
  --text-5xl: 3rem;
  --text-6xl: 3.75rem;

  --leading-tight: 1.2;
  --leading-snug: 1.375;
  --leading-normal: 1.5;
  --leading-relaxed: 1.625;

  --font-normal: 400;
  --font-medium: 500;
  --font-semibold: 600;
  --font-bold: 700;
  --font-extrabold: 800;

  /* Radii */
  --radius-sm: 0.375rem;
  --radius-md: 0.5rem;
  --radius-lg: 0.75rem;
  --radius-xl: 1rem;
  --radius-2xl: 1.25rem;
  --radius-full: 9999px;

  /* Shadows */
  --shadow-sm: 0 1px 2px 0 oklch(0% 0 0 / 0.05);
  --shadow-md: 0 4px 6px -1px oklch(0% 0 0 / 0.07), 0 2px 4px -2px oklch(0% 0 0 / 0.05);
  --shadow-lg: 0 10px 15px -3px oklch(0% 0 0 / 0.08), 0 4px 6px -4px oklch(0% 0 0 / 0.05);
  --shadow-xl: 0 20px 25px -5px oklch(0% 0 0 / 0.08), 0 8px 10px -6px oklch(0% 0 0 / 0.04);
  --shadow-card: 0 1px 3px oklch(0% 0 0 / 0.06), 0 4px 12px oklch(0% 0 0 / 0.04);
  --shadow-card-hover: 0 8px 24px oklch(0% 0 0 / 0.1), 0 2px 6px oklch(0% 0 0 / 0.06);

  /* Transitions */
  --transition-fast: 150ms ease;
  --transition-base: 200ms ease;
  --transition-slow: 300ms ease;

  /* Layout */
  --container-max: 1280px;
  --container-narrow: 1024px;
  --nav-height: 4rem;
}

/* --- Reset & Base --- */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: var(--font-sans);
  font-size: var(--text-base);
  line-height: var(--leading-normal);
  color: var(--text-primary);
  background: var(--bg-white);
}

a {
  color: inherit;
  text-decoration: none;
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

button {
  font-family: inherit;
  cursor: pointer;
  border: none;
  background: none;
}

input, textarea {
  font-family: inherit;
  font-size: inherit;
}

ul, ol {
  list-style: none;
}

/* --- Utilities --- */
.container {
  max-width: var(--container-max);
  margin: 0 auto;
  padding: 0 var(--space-6);
}

.container-narrow {
  max-width: var(--container-narrow);
  margin: 0 auto;
  padding: 0 var(--space-6);
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

/* --- Typography --- */
.heading-1 {
  font-size: var(--text-5xl);
  font-weight: var(--font-extrabold);
  line-height: var(--leading-tight);
  letter-spacing: -0.025em;
}

.heading-2 {
  font-size: var(--text-4xl);
  font-weight: var(--font-bold);
  line-height: var(--leading-tight);
  letter-spacing: -0.02em;
}

.heading-3 {
  font-size: var(--text-3xl);
  font-weight: var(--font-bold);
  line-height: var(--leading-snug);
  letter-spacing: -0.015em;
}

.heading-4 {
  font-size: var(--text-2xl);
  font-weight: var(--font-semibold);
  line-height: var(--leading-snug);
}

.heading-5 {
  font-size: var(--text-xl);
  font-weight: var(--font-semibold);
  line-height: var(--leading-snug);
}

.body-large {
  font-size: var(--text-lg);
  line-height: var(--leading-relaxed);
  color: var(--text-secondary);
}

.body-small {
  font-size: var(--text-sm);
  line-height: var(--leading-normal);
  color: var(--text-muted);
}

/* --- Buttons --- */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-2);
  padding: var(--space-3) var(--space-6);
  font-size: var(--text-sm);
  font-weight: var(--font-semibold);
  border-radius: var(--radius-lg);
  transition: all var(--transition-base);
  white-space: nowrap;
}

.btn-primary {
  background: var(--gradient-primary);
  color: var(--text-on-primary);
  box-shadow: var(--shadow-md);
}

.btn-primary:hover {
  transform: translateY(-1px);
  box-shadow: var(--shadow-lg);
  filter: brightness(1.05);
}

.btn-accent {
  background: var(--gradient-accent);
  color: var(--text-on-primary);
  box-shadow: var(--shadow-md);
}

.btn-accent:hover {
  transform: translateY(-1px);
  box-shadow: var(--shadow-lg);
  filter: brightness(1.05);
}

.btn-secondary {
  background: var(--bg-white);
  color: var(--text-primary);
  border: 1.5px solid oklch(85% 0.02 265);
  box-shadow: var(--shadow-sm);
}

.btn-secondary:hover {
  border-color: var(--brand-primary);
  color: var(--brand-primary);
  box-shadow: var(--shadow-md);
}

.btn-ghost {
  color: var(--text-secondary);
  padding: var(--space-2) var(--space-4);
}

.btn-ghost:hover {
  color: var(--text-primary);
  background: var(--bg-subtle);
}

.btn-large {
  padding: var(--space-4) var(--space-8);
  font-size: var(--text-base);
  border-radius: var(--radius-xl);
}

/* --- Cards --- */
.card {
  background: var(--bg-elevated);
  border-radius: var(--radius-xl);
  box-shadow: var(--shadow-card);
  border: 1px solid oklch(90% 0.01 265);
  transition: all var(--transition-base);
}

.card:hover {
  box-shadow: var(--shadow-card-hover);
}

.card-popular {
  border-color: var(--brand-primary);
  box-shadow: 0 0 0 3px oklch(55% 0.18 255 / 0.1), var(--shadow-card);
}

/* --- Navigation --- */
.nav {
  position: sticky;
  top: 0;
  z-index: 100;
  height: var(--nav-height);
  background: oklch(100% 0 0 / 0.85);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-bottom: 1px solid oklch(90% 0.01 265 / 0.5);
}

.nav-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 100%;
}

.nav-logo {
  font-size: var(--text-xl);
  font-weight: var(--font-extrabold);
  color: var(--text-primary);
  display: flex;
  align-items: center;
  gap: var(--space-2);
}

.nav-logo-mark {
  width: 2rem;
  height: 2rem;
  background: var(--gradient-primary);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  color: white;
  font-size: var(--text-sm);
}

.nav-links {
  display: flex;
  align-items: center;
  gap: var(--space-8);
}

.nav-link {
  font-size: var(--text-sm);
  font-weight: var(--font-medium);
  color: var(--text-secondary);
  transition: color var(--transition-fast);
}

.nav-link:hover {
  color: var(--text-primary);
}

.nav-actions {
  display: flex;
  align-items: center;
  gap: var(--space-3);
}

/* --- Hero --- */
.hero {
  background: var(--gradient-hero);
  padding: var(--space-24) 0 var(--space-20);
  position: relative;
  overflow: hidden;
}

.hero-content {
  text-align: center;
  max-width: 800px;
  margin: 0 auto;
}

.hero-badge {
  display: inline-flex;
  align-items: center;
  gap: var(--space-2);
  padding: var(--space-2) var(--space-4);
  background: oklch(55% 0.18 255 / 0.08);
  color: var(--brand-primary);
  font-size: var(--text-sm);
  font-weight: var(--font-medium);
  border-radius: var(--radius-full);
  margin-bottom: var(--space-6);
}

.hero-title {
  font-size: clamp(2.5rem, 5vw, var(--text-6xl));
  font-weight: var(--font-extrabold);
  line-height: var(--leading-tight);
  letter-spacing: -0.03em;
  margin-bottom: var(--space-6);
  color: var(--text-primary);
}

.hero-subtitle {
  font-size: var(--text-xl);
  line-height: var(--leading-relaxed);
  color: var(--text-secondary);
  margin-bottom: var(--space-8);
  max-width: 640px;
  margin-left: auto;
  margin-right: auto;
}

.hero-actions {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-4);
  flex-wrap: wrap;
}

/* --- Logo Bar --- */
.logo-bar {
  padding: var(--space-12) 0;
  border-top: 1px solid oklch(90% 0.01 265 / 0.5);
}

.logo-bar-text {
  text-align: center;
  font-size: var(--text-sm);
  color: var(--text-muted);
  margin-bottom: var(--space-8);
}

.logo-grid {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-12);
  flex-wrap: wrap;
}

.logo-item {
  font-size: var(--text-lg);
  font-weight: var(--font-bold);
  color: var(--text-muted);
  opacity: 0.6;
  transition: opacity var(--transition-base);
}

.logo-item:hover {
  opacity: 1;
}

/* --- Feature Sections --- */
.feature-section {
  padding: var(--space-24) 0;
}

.feature-section-alt {
  background: var(--bg-surface);
}

.feature-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--space-16);
  align-items: center;
}

.feature-content {
  max-width: 520px;
}

.feature-label {
  display: inline-flex;
  align-items: center;
  gap: var(--space-2);
  padding: var(--space-1) var(--space-3);
  background: var(--brand-accent);
  color: white;
  font-size: var(--text-xs);
  font-weight: var(--font-bold);
  text-transform: uppercase;
  letter-spacing: 0.05em;
  border-radius: var(--radius-sm);
  margin-bottom: var(--space-4);
}

.feature-title {
  font-size: var(--text-4xl);
  font-weight: var(--font-bold);
  line-height: var(--leading-tight);
  letter-spacing: -0.02em;
  margin-bottom: var(--space-4);
}

.feature-desc {
  font-size: var(--text-lg);
  line-height: var(--leading-relaxed);
  color: var(--text-secondary);
  margin-bottom: var(--space-6);
}

.feature-list {
  display: flex;
  flex-direction: column;
  gap: var(--space-4);
}

.feature-list-item {
  display: flex;
  gap: var(--space-3);
}

.feature-list-icon {
  width: 1.5rem;
  height: 1.5rem;
  flex-shrink: 0;
  color: var(--brand-primary);
  margin-top: 2px;
}

.feature-visual {
  background: var(--bg-white);
  border-radius: var(--radius-2xl);
  box-shadow: var(--shadow-xl);
  padding: var(--space-6);
  border: 1px solid oklch(90% 0.01 265);
}

/* --- Use Cases --- */
.use-cases-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: var(--space-6);
}

.use-case-card {
  padding: var(--space-8);
  background: var(--bg-white);
  border-radius: var(--radius-xl);
  border: 1px solid oklch(90% 0.01 265);
  transition: all var(--transition-base);
}

.use-case-card:hover {
  border-color: var(--brand-primary);
  box-shadow: var(--shadow-card-hover);
  transform: translateY(-2px);
}

.use-case-icon {
  width: 3rem;
  height: 3rem;
  background: oklch(55% 0.18 255 / 0.08);
  border-radius: var(--radius-lg);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--brand-primary);
  margin-bottom: var(--space-4);
}

.use-case-title {
  font-size: var(--text-lg);
  font-weight: var(--font-semibold);
  margin-bottom: var(--space-2);
}

.use-case-desc {
  font-size: var(--text-sm);
  color: var(--text-secondary);
  line-height: var(--leading-relaxed);
}

/* --- Features Grid --- */
.features-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: var(--space-5);
}

.feature-item {
  padding: var(--space-6);
  background: var(--bg-white);
  border-radius: var(--radius-lg);
  border: 1px solid oklch(90% 0.01 265);
  transition: all var(--transition-base);
}

.feature-item:hover {
  border-color: oklch(80% 0.03 265);
  box-shadow: var(--shadow-md);
}

.feature-item-icon {
  width: 2.5rem;
  height: 2.5rem;
  background: oklch(55% 0.18 255 / 0.06);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--brand-primary);
  margin-bottom: var(--space-3);
}

.feature-item-title {
  font-size: var(--text-sm);
  font-weight: var(--font-semibold);
  color: var(--text-primary);
}

/* --- Testimonials --- */
.testimonials-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-6);
}

.testimonial-card {
  padding: var(--space-8);
  background: var(--bg-white);
  border-radius: var(--radius-xl);
  border: 1px solid oklch(90% 0.01 265);
  transition: all var(--transition-base);
}

.testimonial-card:hover {
  box-shadow: var(--shadow-card-hover);
}

.testimonial-quote {
  font-size: var(--text-base);
  line-height: var(--leading-relaxed);
  color: var(--text-primary);
  margin-bottom: var(--space-6);
  font-style: italic;
}

.testimonial-author {
  display: flex;
  align-items: center;
  gap: var(--space-3);
}

.testimonial-avatar {
  width: 2.5rem;
  height: 2.5rem;
  border-radius: var(--radius-full);
  background: var(--gradient-primary);
  display: flex;
  align-items: center;
  justify-content: center;
  color: white;
  font-size: var(--text-sm);
  font-weight: var(--font-bold);
}

.testimonial-name {
  font-size: var(--text-sm);
  font-weight: var(--font-semibold);
  color: var(--text-primary);
}

.testimonial-role {
  font-size: var(--text-xs);
  color: var(--text-muted);
}

/* --- CTA Banner --- */
.cta-banner {
  padding: var(--space-20) 0;
  text-align: center;
}

.cta-banner-dark {
  background: var(--bg-dark);
  color: var(--bg-white);
}

.cta-banner-dark .cta-title {
  color: var(--bg-white);
}

.cta-banner-dark .cta-subtitle {
  color: oklch(75% 0.02 265);
}

.cta-title {
  font-size: var(--text-4xl);
  font-weight: var(--font-bold);
  margin-bottom: var(--space-4);
  letter-spacing: -0.02em;
}

.cta-subtitle {
  font-size: var(--text-lg);
  color: var(--text-secondary);
  margin-bottom: var(--space-8);
}

/* --- Footer --- */
.footer {
  background: var(--bg-surface);
  border-top: 1px solid oklch(90% 0.01 265);
  padding: var(--space-16) 0 var(--space-8);
}

.footer-grid {
  display: grid;
  grid-template-columns: 2fr repeat(5, 1fr);
  gap: var(--space-8);
  margin-bottom: var(--space-16);
}

.footer-brand {
  max-width: 280px;
}

.footer-brand-logo {
  font-size: var(--text-xl);
  font-weight: var(--font-extrabold);
  display: flex;
  align-items: center;
  gap: var(--space-2);
  margin-bottom: var(--space-4);
}

.footer-brand-desc {
  font-size: var(--text-sm);
  color: var(--text-muted);
  line-height: var(--leading-relaxed);
}

.footer-column-title {
  font-size: var(--text-sm);
  font-weight: var(--font-semibold);
  color: var(--text-primary);
  margin-bottom: var(--space-4);
}

.footer-links {
  display: flex;
  flex-direction: column;
  gap: var(--space-3);
}

.footer-link {
  font-size: var(--text-sm);
  color: var(--text-muted);
  transition: color var(--transition-fast);
}

.footer-link:hover {
  color: var(--brand-primary);
}

.footer-bottom {
  border-top: 1px solid oklch(90% 0.01 265);
  padding-top: var(--space-8);
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: var(--space-4);
}

.footer-copyright {
  font-size: var(--text-sm);
  color: var(--text-muted);
}

/* --- Pricing --- */
.pricing-hero {
  padding: var(--space-20) 0 var(--space-12);
  text-align: center;
}

.pricing-toggle {
  display: inline-flex;
  align-items: center;
  background: var(--bg-subtle);
  border-radius: var(--radius-full);
  padding: var(--space-1);
  margin-bottom: var(--space-8);
}

.pricing-toggle-btn {
  padding: var(--space-2) var(--space-5);
  font-size: var(--text-sm);
  font-weight: var(--font-medium);
  color: var(--text-muted);
  border-radius: var(--radius-full);
  transition: all var(--transition-base);
}

.pricing-toggle-btn.active {
  background: var(--bg-white);
  color: var(--text-primary);
  box-shadow: var(--shadow-sm);
}

.pricing-save-badge {
  display: inline-flex;
  align-items: center;
  padding: var(--space-1) var(--space-3);
  background: var(--brand-accent);
  color: white;
  font-size: var(--text-xs);
  font-weight: var(--font-bold);
  border-radius: var(--radius-sm);
  margin-left: var(--space-2);
}

.pricing-slider {
  max-width: 400px;
  margin: 0 auto var(--space-12);
}

.pricing-slider-label {
  display: flex;
  justify-content: space-between;
  font-size: var(--text-sm);
  color: var(--text-muted);
  margin-bottom: var(--space-2);
}

.pricing-slider-input {
  width: 100%;
  height: 6px;
  -webkit-appearance: none;
  appearance: none;
  background: oklch(85% 0.02 265);
  border-radius: var(--radius-full);
  outline: none;
}

.pricing-slider-input::-webkit-slider-thumb {
  -webkit-appearance: none;
  appearance: none;
  width: 20px;
  height: 20px;
  background: var(--brand-primary);
  border-radius: var(--radius-full);
  cursor: pointer;
  box-shadow: var(--shadow-md);
}

.pricing-slider-input::-moz-range-thumb {
  width: 20px;
  height: 20px;
  background: var(--brand-primary);
  border-radius: var(--radius-full);
  cursor: pointer;
  border: none;
  box-shadow: var(--shadow-md);
}

.pricing-cards {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: var(--space-5);
  margin-bottom: var(--space-16);
}

.pricing-card {
  padding: var(--space-8);
  background: var(--bg-white);
  border-radius: var(--radius-xl);
  border: 1px solid oklch(90% 0.01 265);
  transition: all var(--transition-base);
  position: relative;
}

.pricing-card:hover {
  box-shadow: var(--shadow-card-hover);
}

.pricing-card-popular {
  border-color: var(--brand-primary);
  box-shadow: 0 0 0 3px oklch(55% 0.18 255 / 0.08), var(--shadow-card);
}

.pricing-card-badge {
  position: absolute;
  top: -1px;
  left: 50%;
  transform: translateX(-50%);
  padding: var(--space-1) var(--space-4);
  background: var(--brand-primary);
  color: white;
  font-size: var(--text-xs);
  font-weight: var(--font-bold);
  border-radius: 0 0 var(--radius-md) var(--radius-md);
}

.pricing-card-name {
  font-size: var(--text-lg);
  font-weight: var(--font-semibold);
  margin-bottom: var(--space-2);
}

.pricing-card-price {
  font-size: var(--text-4xl);
  font-weight: var(--font-extrabold);
  color: var(--text-primary);
  margin-bottom: var(--space-1);
}

.pricing-card-price span {
  font-size: var(--text-base);
  font-weight: var(--font-normal);
  color: var(--text-muted);
}

.pricing-card-desc {
  font-size: var(--text-sm);
  color: var(--text-muted);
  margin-bottom: var(--space-6);
  min-height: 2.5rem;
}

.pricing-card-features {
  display: flex;
  flex-direction: column;
  gap: var(--space-3);
  margin-bottom: var(--space-8);
}

.pricing-card-feature {
  display: flex;
  align-items: flex-start;
  gap: var(--space-2);
  font-size: var(--text-sm);
  color: var(--text-secondary);
}

.pricing-card-feature svg {
  width: 1rem;
  height: 1rem;
  color: var(--brand-primary);
  flex-shrink: 0;
  margin-top: 2px;
}

.pricing-card-cta {
  width: 100%;
}

/* --- Comparison Table --- */
.comparison-table-wrap {
  overflow-x: auto;
  margin-bottom: var(--space-16);
}

.comparison-table {
  width: 100%;
  border-collapse: collapse;
  font-size: var(--text-sm);
}

.comparison-table th,
.comparison-table td {
  padding: var(--space-4) var(--space-5);
  text-align: left;
  border-bottom: 1px solid oklch(90% 0.01 265);
}

.comparison-table th {
  font-weight: var(--font-semibold);
  color: var(--text-primary);
  background: var(--bg-surface);
}

.comparison-table th:first-child {
  border-radius: var(--radius-lg) 0 0 0;
}

.comparison-table th:last-child {
  border-radius: 0 var(--radius-lg) 0 0;
}

.comparison-table td {
  color: var(--text-secondary);
}

.comparison-table tr:hover td {
  background: var(--bg-surface);
}

.comparison-table .check {
  color: var(--brand-primary);
  font-weight: var(--font-bold);
}

.comparison-table .dash {
  color: var(--text-muted);
}

/* --- FAQ --- */
.faq-list {
  max-width: 768px;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  gap: var(--space-3);
}

.faq-item {
  background: var(--bg-white);
  border: 1px solid oklch(90% 0.01 265);
  border-radius: var(--radius-lg);
  overflow: hidden;
  transition: all var(--transition-base);
}

.faq-item:hover {
  border-color: oklch(80% 0.03 265);
}

.faq-question {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--space-5) var(--space-6);
  font-size: var(--text-base);
  font-weight: var(--font-medium);
  color: var(--text-primary);
  text-align: left;
  background: none;
  border: none;
  cursor: pointer;
}

.faq-question svg {
  width: 1.25rem;
  height: 1.25rem;
  color: var(--text-muted);
  flex-shrink: 0;
  transition: transform var(--transition-base);
}

.faq-item.open .faq-question svg {
  transform: rotate(180deg);
}

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height var(--transition-slow), padding var(--transition-slow);
}

.faq-item.open .faq-answer {
  max-height: 500px;
  padding: 0 var(--space-6) var(--space-5);
}

.faq-answer p {
  font-size: var(--text-sm);
  line-height: var(--leading-relaxed);
  color: var(--text-secondary);
}

/* --- Cookie Banner --- */
.cookie-banner {
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  z-index: 200;
  background: var(--bg-white);
  border-top: 1px solid oklch(90% 0.01 265);
  box-shadow: var(--shadow-xl);
  padding: var(--space-5) 0;
  transform: translateY(100%);
  transition: transform var(--transition-slow);
}

.cookie-banner.show {
  transform: translateY(0);
}

.cookie-banner-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-6);
  flex-wrap: wrap;
}

.cookie-banner-text {
  font-size: var(--text-sm);
  color: var(--text-secondary);
  flex: 1;
  min-width: 280px;
}

.cookie-banner-actions {
  display: flex;
  gap: var(--space-3);
  flex-shrink: 0;
}

/* --- Cookie Modal --- */
.cookie-modal-overlay {
  position: fixed;
  inset: 0;
  z-index: 300;
  background: oklch(0% 0 0 / 0.4);
  backdrop-filter: blur(4px);
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 0;
  visibility: hidden;
  transition: all var(--transition-base);
}

.cookie-modal-overlay.show {
  opacity: 1;
  visibility: visible;
}

.cookie-modal {
  background: var(--bg-white);
  border-radius: var(--radius-xl);
  box-shadow: var(--shadow-xl);
  max-width: 560px;
  width: 90%;
  max-height: 80vh;
  overflow-y: auto;
  padding: var(--space-8);
  transform: scale(0.95);
  transition: transform var(--transition-base);
}

.cookie-modal-overlay.show .cookie-modal {
  transform: scale(1);
}

.cookie-modal-title {
  font-size: var(--text-xl);
  font-weight: var(--font-bold);
  margin-bottom: var(--space-2);
}

.cookie-modal-desc {
  font-size: var(--text-sm);
  color: var(--text-secondary);
  margin-bottom: var(--space-6);
}

.cookie-category {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--space-4) 0;
  border-bottom: 1px solid oklch(90% 0.01 265);
}

.cookie-category-name {
  font-size: var(--text-sm);
  font-weight: var(--font-semibold);
}

.cookie-category-desc {
  font-size: var(--text-xs);
  color: var(--text-muted);
}

/* Toggle Switch */
.toggle-switch {
  position: relative;
  width: 44px;
  height: 24px;
  background: oklch(85% 0.02 265);
  border-radius: var(--radius-full);
  cursor: pointer;
  transition: background var(--transition-base);
  flex-shrink: 0;
}

.toggle-switch.on {
  background: var(--brand-primary);
}

.toggle-switch::after {
  content: '';
  position: absolute;
  top: 2px;
  left: 2px;
  width: 20px;
  height: 20px;
  background: white;
  border-radius: var(--radius-full);
  transition: transform var(--transition-base);
  box-shadow: var(--shadow-sm);
}

.toggle-switch.on::after {
  transform: translateX(20px);
}

.cookie-modal-actions {
  display: flex;
  gap: var(--space-3);
  margin-top: var(--space-6);
  justify-content: flex-end;
}

/* --- Auth Pages --- */
.auth-page {
  min-height: 100vh;
  display: flex;
}

.auth-panel {
  flex: 1;
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding: var(--space-12);
  max-width: 480px;
  margin: 0 auto;
}

.auth-sidebar {
  flex: 1;
  background: var(--gradient-hero);
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding: var(--space-16);
  position: relative;
}

.auth-logo {
  font-size: var(--text-xl);
  font-weight: var(--font-extrabold);
  display: flex;
  align-items: center;
  gap: var(--space-2);
  margin-bottom: var(--space-12);
}

.auth-title {
  font-size: var(--text-3xl);
  font-weight: var(--font-bold);
  margin-bottom: var(--space-2);
}

.auth-subtitle {
  font-size: var(--text-base);
  color: var(--text-secondary);
  margin-bottom: var(--space-8);
}

.social-buttons {
  display: flex;
  flex-direction: column;
  gap: var(--space-3);
  margin-bottom: var(--space-6);
}

.social-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-3);
  padding: var(--space-3) var(--space-5);
  background: var(--bg-white);
  border: 1.5px solid oklch(85% 0.02 265);
  border-radius: var(--radius-lg);
  font-size: var(--text-sm);
  font-weight: var(--font-medium);
  color: var(--text-primary);
  transition: all var(--transition-base);
}

.social-btn:hover {
  border-color: var(--brand-primary);
  background: var(--bg-surface);
}

.divider {
  display: flex;
  align-items: center;
  gap: var(--space-4);
  margin-bottom: var(--space-6);
  color: var(--text-muted);
  font-size: var(--text-sm);
}

.divider::before,
.divider::after {
  content: '';
  flex: 1;
  height: 1px;
  background: oklch(90% 0.01 265);
}

.auth-input {
  width: 100%;
  padding: var(--space-3) var(--space-4);
  border: 1.5px solid oklch(85% 0.02 265);
  border-radius: var(--radius-lg);
  font-size: var(--text-sm);
  color: var(--text-primary);
  background: var(--bg-white);
  transition: border-color var(--transition-base), box-shadow var(--transition-base);
  margin-bottom: var(--space-4);
}

.auth-input:focus {
  outline: none;
  border-color: var(--brand-primary);
  box-shadow: 0 0 0 3px oklch(55% 0.18 255 / 0.1);
}

.auth-input::placeholder {
  color: var(--text-muted);
}

.auth-btn {
  width: 100%;
  padding: var(--space-3) var(--space-5);
  background: var(--gradient-primary);
  color: white;
  font-size: var(--text-sm);
  font-weight: var(--font-semibold);
  border-radius: var(--radius-lg);
  transition: all var(--transition-base);
}

.auth-btn:hover {
  filter: brightness(1.05);
  box-shadow: var(--shadow-md);
}

.auth-footer {
  margin-top: var(--space-6);
  font-size: var(--text-xs);
  color: var(--text-muted);
  text-align: center;
  line-height: var(--leading-relaxed);
}

.auth-footer a {
  color: var(--brand-primary);
  text-decoration: underline;
  text-underline-offset: 2px;
}

.auth-link {
  text-align: center;
  margin-top: var(--space-6);
  font-size: var(--text-sm);
  color: var(--text-secondary);
}

.auth-link a {
  color: var(--brand-primary);
  font-weight: var(--font-semibold);
}

/* Sidebar testimonial */
.sidebar-testimonial {
  max-width: 400px;
}

.sidebar-testimonial-quote {
  font-size: var(--text-xl);
  line-height: var(--leading-relaxed);
  color: var(--text-primary);
  margin-bottom: var(--space-8);
  font-style: italic;
}

.sidebar-testimonial-author {
  display: flex;
  align-items: center;
  gap: var(--space-4);
}

.sidebar-testimonial-avatar {
  width: 3rem;
  height: 3rem;
  border-radius: var(--radius-full);
  background: var(--gradient-primary);
  display: flex;
  align-items: center;
  justify-content: center;
  color: white;
  font-size: var(--text-base);
  font-weight: var(--font-bold);
}

.sidebar-testimonial-name {
  font-size: var(--text-base);
  font-weight: var(--font-semibold);
}

.sidebar-testimonial-role {
  font-size: var(--text-sm);
  color: var(--text-secondary);
}

/* --- Stats --- */
.stats-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-8);
}

.stat-item {
  text-align: center;
  padding: var(--space-8);
}

.stat-number {
  font-size: var(--text-5xl);
  font-weight: var(--font-extrabold);
  color: var(--brand-primary);
  line-height: 1;
  margin-bottom: var(--space-3);
}

.stat-label {
  font-size: var(--text-base);
  color: var(--text-secondary);
}

/* --- Blog Teasers --- */
.blog-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: var(--space-6);
}

.blog-card {
  padding: var(--space-8);
  background: var(--bg-white);
  border-radius: var(--radius-xl);
  border: 1px solid oklch(90% 0.01 265);
  transition: all var(--transition-base);
}

.blog-card:hover {
  border-color: var(--brand-primary);
  box-shadow: var(--shadow-card-hover);
}

.blog-card-title {
  font-size: var(--text-lg);
  font-weight: var(--font-semibold);
  margin-bottom: var(--space-3);
  line-height: var(--leading-snug);
}

.blog-card-desc {
  font-size: var(--text-sm);
  color: var(--text-secondary);
  line-height: var(--leading-relaxed);
}

/* --- Section Header --- */
.section-header {
  text-align: center;
  max-width: 640px;
  margin: 0 auto var(--space-12);
}

.section-title {
  font-size: var(--text-4xl);
  font-weight: var(--font-bold);
  line-height: var(--leading-tight);
  letter-spacing: -0.02em;
  margin-bottom: var(--space-4);
}

.section-subtitle {
  font-size: var(--text-lg);
  color: var(--text-secondary);
  line-height: var(--leading-relaxed);
}

/* --- Enterprise specific --- */
.enterprise-hero {
  background: var(--gradient-hero);
  padding: var(--space-24) 0 var(--space-16);
}

.security-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: var(--space-5);
}

.security-item {
  display: flex;
  align-items: flex-start;
  gap: var(--space-3);
  padding: var(--space-5);
  background: var(--bg-white);
  border-radius: var(--radius-lg);
  border: 1px solid oklch(90% 0.01 265);
}

.security-item svg {
  width: 1.25rem;
  height: 1.25rem;
  color: var(--brand-primary);
  flex-shrink: 0;
  margin-top: 2px;
}

.security-item-text {
  font-size: var(--text-sm);
  color: var(--text-secondary);
  line-height: var(--leading-relaxed);
}

/* --- Integrations --- */
.integrations-grid {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: var(--space-4);
}

.integration-item {
  aspect-ratio: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg-white);
  border-radius: var(--radius-lg);
  border: 1px solid oklch(90% 0.01 265);
  font-size: var(--text-sm);
  font-weight: var(--font-semibold);
  color: var(--text-muted);
  transition: all var(--transition-base);
}

.integration-item:hover {
  border-color: var(--brand-primary);
  color: var(--brand-primary);
  box-shadow: var(--shadow-md);
}

/* --- Responsive --- */
@media (max-width: 1024px) {
  .feature-grid {
    grid-template-columns: 1fr;
    gap: var(--space-10);
  }

  .feature-visual {
    order: -1;
  }

  .use-cases-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .features-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .testimonials-grid {
    grid-template-columns: 1fr;
  }

  .pricing-cards {
    grid-template-columns: repeat(2, 1fr);
  }

  .footer-grid {
    grid-template-columns: repeat(3, 1fr);
  }

  .stats-grid {
    grid-template-columns: 1fr;
  }

  .integrations-grid {
    grid-template-columns: repeat(3, 1fr);
  }
}

@media (max-width: 768px) {
  .nav-links {
    display: none;
  }

  .hero {
    padding: var(--space-16) 0 var(--space-12);
  }

  .hero-actions {
    flex-direction: column;
    width: 100%;
  }

  .hero-actions .btn {
    width: 100%;
  }

  .use-cases-grid {
    grid-template-columns: 1fr;
  }

  .features-grid {
    grid-template-columns: 1fr;
  }

  .pricing-cards {
    grid-template-columns: 1fr;
  }

  .footer-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .auth-page {
    flex-direction: column;
  }

  .auth-sidebar {
    display: none;
  }

  .blog-grid {
    grid-template-columns: 1fr;
  }

  .security-grid {
    grid-template-columns: 1fr;
  }

  .heading-1 {
    font-size: var(--text-4xl);
  }

  .heading-2 {
    font-size: var(--text-3xl);
  }

  .section-title {
    font-size: var(--text-3xl);
  }
}

@media (max-width: 480px) {
  .footer-grid {
    grid-template-columns: 1fr;
  }

  .cookie-banner-inner {
    flex-direction: column;
    align-items: stretch;
  }

  .cookie-banner-actions {
    justify-content: stretch;
  }

  .cookie-banner-actions .btn {
    flex: 1;
  }
}
